<p><a href="/uni?view=modules"><?= e(t('Modules & grades')) ?></a> · <a href="/uni?view=assignments"><?= e(t('Assignments')) ?></a> · <a href="/uni?view=exams"><?= e(t('Exams')) ?></a> · <a href="/career"><?= e(t('Career applications')) ?></a></p>
<?php if($kind==='attendance'): ?><section class="card"><h2><?= e(t('Attendance & timetable warnings')) ?></h2><?php foreach(StudyService::attendance()as $module=>$v):$m=Db::one('SELECT name FROM uni_modules WHERE id=?',[$module]); ?><p><?= e($m['name']??t('Removed module')) ?> · <?= e($v['percent']??t('No counted classes')) ?>% · <?= e($v['present']) ?>/<?= e($v['count']) ?> <?= e(t('present')) ?> <?= $v['percent']!==null&&$v['percent']<$v['threshold']?' · Below your warning threshold':'' ?></p><?php endforeach; ?><?php foreach(StudyService::clashes()as [$a,$b]): ?><p role="status"><?= e(t('Timetable clash:')) ?> <?= e($a['start_time']) ?>–<?= e($a['end_time']) ?> <?= e(t('and')) ?> <?= e($b['start_time']) ?>–<?= e($b['end_time']) ?> <?= e(t('on weekday')) ?> <?= e($a['day']) ?>.</p><?php endforeach; ?></section><?php endif; ?>
<?php if(in_array($kind,['gpa_scenarios','grade_thresholds'],true)):$s=StudyService::scenario(); ?><section class="card"><h2><?= e(t('Scenario GPA')) ?></h2><p><?= e($s['gpa']??t('No graded/scenario credits')) ?> <?= e(t('across')) ?> <?= e($s['credits']) ?> <?= e(t('included credits.')) ?></p><?php if($s['unknown']): ?><p><?= e(t('Not included until a grade or matching mark band is available:')) ?> <?= e(implode(', ',$s['unknown'])) ?>.</p><?php endif; ?><p><?= e(t('These scenarios do not replace your recorded grades. Enter your institution\'s actual mark bands and source.')) ?></p></section><?php endif; ?>
<?php if($kind==='fee_plans'||$kind==='instalments'): ?><section class="card"><h2><?= e(t('Academic fee balances')) ?></h2><?php foreach(StudyService::rows('fee_plans')as $plan):$paid=0;foreach(StudyService::rows('instalments')as $inst)if($inst['fields']['plan']===$plan['id']&&$inst['fields']['paid_on']!==null)$paid+=$inst['fields']['amount']; ?><p><?= e($plan['fields']['title']) ?> <?= e(t('· Paid')) ?> <?= money($paid) ?> <?= e(t('· Remaining')) ?> <?= money($plan['fields']['total']-$paid) ?></p><?php endforeach; ?><p class="muted"><?= e(t('Fee records are tracking entries; they do not debit Money accounts.')) ?></p></section><?php endif; ?>
